-- Generated from CEFR-J Wordlist v1.6 and Free Dictionary API responses.
-- Review source citations in source_metadata before distribution.
-- Idempotent by import_key and deck_words composite primary key.
-- Reviewed Vietnamese glosses from Wiktionary are attributed per word.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
SET LOCAL standard_conforming_strings = on;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='words' AND column_name='source_metadata') THEN
    RAISE EXCEPTION 'Week 4 vocabulary migration V1_2 is not applied';
  END IF;
END $$;
LOCK TABLE public.decks IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM decks WHERE title = 'A1 – Core Vocabulary 01' AND description IS DISTINCT FROM 'English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch a21a78d895e15d43535e3368600e906bb48be738a6ec681d7a85379cee2d8bcd.') THEN
    RAISE EXCEPTION 'A deck titled % already exists with different content', 'A1 – Core Vocabulary 01';
  END IF;
  IF (SELECT count(*) FROM decks WHERE title = 'A1 – Core Vocabulary 01') > 1 THEN
    RAISE EXCEPTION 'More than one deck already has title %', 'A1 – Core Vocabulary 01';
  END IF;
END $$;
INSERT INTO decks(title, description, level, is_published)
SELECT 'A1 – Core Vocabulary 01', 'English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch a21a78d895e15d43535e3368600e906bb48be738a6ec681d7a85379cee2d8bcd.', 'A1', TRUE
WHERE NOT EXISTS (SELECT 1 FROM decks WHERE title='A1 – Core Vocabulary 01' AND description='English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch a21a78d895e15d43535e3368600e906bb48be738a6ec681d7a85379cee2d8bcd.');
