    RAISE EXCEPTION 'A deck titled % already exists with different content', 'A1 – Core Vocabulary 02';
  END IF;
  IF (SELECT count(*) FROM decks WHERE title = 'A1 – Core Vocabulary 02') > 1 THEN
    RAISE EXCEPTION 'More than one deck already has title %', 'A1 – Core Vocabulary 02';
  END IF;
END $$;
INSERT INTO decks(title, description, level, is_published)
SELECT 'A1 – Core Vocabulary 02', 'English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch fd9053d26cdbdd80d59a2ed33e05a25135dbf511fc9e831d9872cd9cfe2d6cc3.', 'A1', TRUE
WHERE NOT EXISTS (SELECT 1 FROM decks WHERE title='A1 – Core Vocabulary 02' AND description='English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch fd9053d26cdbdd80d59a2ed33e05a25135dbf511fc9e831d9872cd9cfe2d6cc3.');
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM decks WHERE title = 'A1 – Core Vocabulary 03' AND description IS DISTINCT FROM 'English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch 9ac1e24d638c31bffb41cef05c677079ae3220ce3fe9eabdf78f472446e3bc86.') THEN
