2","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","senseLocator":"noun:2","sourceGloss":"Nghệ thuật; mỹ thuật.","reviewStatus":"VERIFIED","reviewReason":"Nghĩa hoạt động sáng tạo, phù hợp ví dụ về graffiti.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
