on":"Mục tiếng Anh xác nhận giới từ chỉ nơi chốn và bảng dịch có ở tại. Trang tiếng Việt cũng giải thích nghĩa vị trí.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
INSERT INTO words(headword, ipa, meaning_vi, example_en, example_vi, audio_url, part_of_speech, cefr_level, definition_en, category_main, category_sub, threshold_category, import_key, source_metadata) VALUES ('aunt', '/ɑ(ː)nt/', 'cô, dì, thím, mợ, bác gái', 'My aunt is my mother''s younger sister.', 'Dì tôi là em gái của mẹ tôi.', NULL, 'noun', 'A1', 'The sister or sister-in-law of one’s parent.', 'Family life', NULL, 'Personal identification', '53c7e661c4121199ac113e2772be8b8d00dffdde5a84f74ae14a7464b741164e', '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","url":"https://cefr-j.org/download_eng","version":"1.6","worksheet":"A1","row":59,"citation":"The CEFR-J Wordlist Version 1.6. Compiled by Yukio Tono, Tokyo University of Foreign Studies. Retrieved from https://cefr-j.org/download_eng on 2026-11-18.","licenseNote":"Official page allows research and commercial use with proper acknowledgement; cite the wordlist."},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/aunt","underlyingSource":"English Wiktionary","underlyingPage":"https://en.wiktionary.org/wiki/aunt","license":"CC BY-SA 3.0 (or later) and GFDL as stated by the API maintainer","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"First non-empty definition in an API sense whose partOfSpeech exactly matches CEFR-J POS.","retrievedAtUtc":"2026-11-18T02:30:35.483164+00:00","reviewStatus":"Source/POS matched; not independently human reviewed.","audioOmitted":"Audio URL not stored because its separate reuse license was not verified."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/aunt","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","senseLocator":"noun:1","sourceGloss":"Cô, dì, thím, mợ, bác gái.","reviewStatus":"VERIFIED","reviewReason":"Tập hợp cách gọi tiếng Việt tùy quan hệ họ hàng, gồm cả quan hệ qua hôn nhân.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
INSERT INTO words(headword, ipa, meaning_vi, example_en, example_vi, audio_url, part_of_speech, cefr_level, definition_en, category_main, category_sub, threshold_category, import_key, source_metadata) VALUES ('autumn', '/ˈɔːtəm/', 'mùa thu', 'The leaves turn yellow in autumn.', 'Lá chuyển sang màu vàng vào mùa thu.', NULL, 'noun', 'A1', 'Traditionally the third of the four seasons, when deciduous trees lose their leaves; typically regarded as being from September 24 to December 22 in parts of the Northern Hemisphere, and the months of March, April and May in the Southern Hemisphere.', NULL, NULL, NULL, 'c4dfaca0297671bac68f6dca1f2f3e6bc38316e135443802c8f0145f203a19d0', '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","url":"https://cefr-j.org/download_eng","version":"1.6","worksheet":"A1","row":60,"citation":"The CEFR-J Wordlist Version 1.6. Compiled by Yukio Tono, Tokyo University of Foreign Studies. Retrieved from https://cefr-j.org/download_eng on 2026-11-18.","licenseNote":"Official page allows research and commercial use with proper acknowledgement; cite the wordlist."},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/autumn","underlyingSource":"English Wiktionary","underlyingPage":"https://en.wiktionary.org/wiki/autumn","license":"CC BY-SA 3.0 (or later) and GFDL as stated by the API maintainer","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"First non-empty definition in an API sense whose partOfSpeech exactly matches CEFR-J POS.","retrievedAtUtc":"2026-11-18T02:30:39.655693+00:00","reviewStatus":"Source/POS matched; not independently human reviewed.","audioOmitted":"Audio URL not stored because its separate reuse license was not verified."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/autumn","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","senseLocator":"noun:1","sourceGloss":"Mùa thu.","reviewStatus":"VERIFIED","reviewReason":"Khớp tên mùa. Nghĩa bóng về tuổi tác không thuộc mục này.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
INSERT INTO words(headword, ipa, meaning_vi, example_en, example_vi, audio_url, part_of_speech, cefr_level, definition_en, category_main, category_sub, threshold_category, import_key, source_metadata) VALUES ('away', '/əˈweɪ/', 'đi xa', 'He went away on vacation.', 'Anh ấy đi xa để nghỉ mát.', NULL, 'adverb', 'A1', 'From a place, hence.', NULL, NULL, NULL, 'd013d8b0cbad37b411db709c3e4d638aa7691d2c6b3f08926ce9fb2c39b96846', '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","url":"https://cefr-j.org/download_eng","version":"1.6","worksheet":"A1","row":62,"citation":"The CEFR-J Wordlist Version 1.6. Compiled by Yukio Tono, Tokyo University of Foreign Studies. Retrieved from https://cefr-j.org/download_eng on 2026-11-18.","licenseNote":"Official page allows research and commercial use with proper acknowledgement; cite the wordlist."},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/away","underlyingSource":"English Wiktionary","underlyingPage":"https://en.wiktionary.org/wiki/away","license":"CC BY-SA 3.0 (or later) and GFDL as stated by the API maintainer","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"First non-empty definition in an API sense whose partOfSpeech exactly matches CEFR-J POS.","retrievedAtUtc":"2026-11-18T02:30:48.028415+00:00","reviewStatus":"Source/POS matched; not independently human reviewed.","audioOmitted":"Audio URL not stored because its separate reuse license was not verified."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/away","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","senseLocator":"adv:1","sourceGloss":"Xa, xa cách, rời xa, xa ra, đi (xa).","reviewStatus":"VERIFIED","reviewReason":"Phó từ diễn tả rời khỏi một nơi. Hợp ví dụ đi xa để nghỉ.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"Free Dictionary API","englishUrl":"https://api.dictionaryapi.dev/api/v2/entries/en/away","vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
INSERT INTO words(headword, ipa, meaning_vi, example_en, example_vi, audio_url, part_of_speech, cefr_level, definition_en, category_main, category_sub, threshold_category, import_key, source_metadata) VALUES ('baby', '/ˈbeɪbi/', 'em bé', 'The baby is sleeping.', 'Em bé đang ngủ.', NULL, 'noun', 'A1', 'A very young human, particularly from birth to a couple of years old or until walking is fully mastered.', 'Family life', NULL, 'Personal identification', '281fe5670aa97ddead163602e0704e7ca97400564767ad29feb27755b8c5f6d5', '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","url":"https://cefr-j.org/download_eng","version":"1.6","worksheet":"A1","row":63,"citation":"The CEFR-J Wordlist Version 1.6. Compiled by Yukio Tono, Tokyo University of Foreign Studies. Retrieved from https://cefr-j.org/download_eng on 2026-11-18.","licenseNote":"Official page allows research and commercial use with proper acknowledgement; cite the wordlist."},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/baby","underlyingSource":"English Wiktionary","underlyingPage":"https://en.wiktionary.org/wiki/baby","license":"CC BY-SA 3.0 (or later) and GFDL as stated by the API maintainer","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"First non-empty definition in an API sense whose partOfSpeech exactly matches CEFR-J POS.","retrievedAtUtc":"2026-11-18T02:30:52.240181+00:00","reviewStatus":"Source/POS matched; not independently human reviewed.","audioOmitted":"Audio URL not stored because its separate reuse license was not verified."},"vietnamese":{"url":"https://vi.wiktionary.org/w/index.php?title=baby&oldid=2112068","source":"Vietnamese Wiktionary, direct entry","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","senseLocator":"noun:direct","sourceGloss":"em bé","reviewStatus":"VERIFIED","reviewReason":"Trang trực tiếp ghi em bé trong phần danh từ tiếng Anh. Bản trích xuất bỏ qua cấu trúc cũ của mục từ.","adaptation":"Selected and normalized the relevant part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}') ON CONFLICT (import_key) DO NOTHING;
