    SELECT 1 FROM (VALUES ('73005242d746894adcc8bde2a6354b8d9f06cbe128384924245fb7f919475cdf', 1, 'bất cứ ai'), ('d99988b29d6961d69729dd9bb1f728efbdc476795d626560eaa98fa01875f1c2', 2, 'vòng quanh'), ('c4dfaca0297671bac68f6dca1f2f3e6bc38316e135443802c8f0145f203a19d0', 3, 'mùa thu'), ('d013d8b0cbad37b411db709c3e4d638aa7691d2c6b3f08926ce9fb2c39b96846', 4, 'đi xa'), ('281fe5670aa97ddead163602e0704e7ca97400564767ad29feb27755b8c5f6d5', 5, 'em bé')) AS expected(import_key, sort_order, meaning_vi)
    FULL JOIN (SELECT w.import_key, dw.sort_order, w.meaning_vi FROM decks d
               JOIN deck_words dw ON dw.deck_id=d.id JOIN words w ON w.id=dw.word_id
               WHERE d.title='A1 – Core Vocabulary 03' AND d.description='English Learning App Week 4, CEFR-J v1.6 A1, verified Vietnamese senses. Batch 9ac1e24d638c31bffb41cef05c677079ae3220ce3fe9eabdf78f472446e3bc86.') actual
    ON actual.import_key=expected.import_key AND actual.sort_order=expected.sort_order
    AND actual.meaning_vi=expected.meaning_vi
    WHERE actual.import_key IS NULL OR expected.import_key IS NULL
  ) THEN
    RAISE EXCEPTION 'Existing deck links or word meanings differ for %', 'A1 – Core Vocabulary 03';
  END IF;
END $$;
-- Summary emitted by the runner after COMMIT; verify with the queries in VOCABULARY_IMPORT_GUIDE.md.
COMMIT;
